let colors = {
	lightBgs: ['#6bd489', '#e8c3dc'],
	lights: ['#78f1d9', '#ffd400', '#52e77c', '#ec9bd3'],
	darks: ['#f57a00', '#3e34ac', '#470320'],
	darkBgs: ['#32908f', '#45255e', '#05332c'],
}

let colorOpts = [{
		bg: '#6bd489',
		palette: ['#3e34ac', '#32908f'],
	},
	{
		bg: '#e8c3dc',
		palette: ['#f57a00', '#470320'],
