	},
]

class Sketch {

	constructor() {
		this.styleOpts = shuffle(Object.keys(celldr))
		this.gridStage = 'in'
		this.cellSize = 50
		this.freqShape = 0.1
		this.freqColor = 0.03
		this.cells = []
		this.lastTime = null
		this.noiseIndex = 0
		this.progress = 0
		this.durationGridWait = 1000
		this.durationGridIn = 800
		this.durationGridOut = 600
		this.durationCellIn = 500
		this.durationCellOut = 200
		this.easeCellIn = 'inCirc'
		this.easeCellOut = 'outCirc'
		this.easeGridIn = 'inSine'
		this.easeGridOut = 'outSine'

		this.updateSizes()
		this.updateColors()
		this.updateCells()
	}

	updateColors() {
		let cols = random(colorOpts)
		this.bg = cols.bg
		this.palette = cols.palette
	}

	updateSizes() {
		this.cellSize = floor(random(40, 80))
	}

	updateCells() {
		this.noiseIndex++
		this.cells = []
		this.sidesX = ceil(width / this.cellSize)
		this.sidesY = ceil(height / this.cellSize)

		for (let nx = 0; nx < this.sidesX; nx++) {
			for (let ny = 0; ny < this.sidesY; ny++) {
				let cell = {
					nx,
					ny,
					rot: 0,
					p: 0,
					pe: 0
				}
				this.updateCell(cell)
				this.cells.push(cell)
			}
		}

		this.cells = shuffle(this.cells)
		this.gridStage = 'in'
		this.progress = 0
	}

	updateCell(cell) {
		let n = noise(cell.nx * this.freqShape, cell.ny * this.freqShape, this.noiseIndex)
		let nx = floor(n * this.styleOpts.length * 2)
		cell.style = this.styleOpts[nx % this.styleOpts.length]

		let nColor = noise(cell.nx * this.freqColor, cell.ny * this.freqColor, this.noiseIndex)
		nColor = floor(nColor * this.palette.length * 2)

		let rotOptions = [0, PI * 0.5, PI, PI * 1.5]
		let nr = floor((nColor + random(0.4)) * 4)
		cell.rot = rotOptions[nr % rotOptions.length]

		cell.color = this.palette[nColor % this.palette.length]
		cell.color2 = this.palette[(nColor + 1) % this.palette.length]
		cell.p = 0
	}

	draw() {
		let t = millis()
		if (!this.lastTime) this.lastTime = t
		this.delta = t - this.lastTime
		this.lastTime = t

		background(this.bg)

		if (this.gridStage === 'in') {
			this.progress = min(1, this.progress + this.delta / this.durationGridIn)
			let p = ease[this.easeGridIn](this.progress)
			let currentCell = round(p * (this.cells.length - 1))

			let allDone = true
			for (let i = 0; i <= currentCell; i++) {
				var cell = this.cells[i]
				cell.p = min(1, cell.p + this.delta / this.durationCellIn)
				cell.pe = ease[this.easeCellIn](cell.p)
				if (cell.p < 1) allDone = false
			}
			this.drawCells()

			if (this.progress >= 1 && allDone) {
				this.progress = 0
				this.gridStage = 'wait'
			}
		} else if (this.gridStage === 'wait') {
			this.progress = min(1, this.progress + this.delta / this.durationGridWait)
			this.drawCells()
			if (this.progress >= 1) {
				this.progress = 0
				this.gridStage = 'out'
			}
		} else if (this.gridStage === 'out') {
			this.progress = min(1, this.progress + this.delta / this.durationGridOut)
			var p = ease[this.easeGridOut](this.progress)
			var currentCell = round((1 - p) * (this.cells.length - 1))

			var allDone = true
			for (let i = currentCell; i < this.cells.length; i++) {
				var cell = this.cells[i]
				cell.p = max(0, cell.p - this.delta / this.durationCellOut)
				cell.pe = ease[this.easeCellOut](cell.p)
				if (cell.p > 0) allDone = false
			}

			this.drawCells()
			if (this.progress >= 1 && allDone) {
				this.updateCells()
			}
		}
	}

	drawCells() {
		for (let i = 0; i < this.cells.length; i++) {
			var cell = this.cells[i]
			let x = cell.nx * this.cellSize
			let y = cell.ny * this.cellSize
			if (cell.p === 0) continue

			push()
			beginClip()
			rect(x, y, this.cellSize)
			endClip()

			this.cellTransform(x, y, this.cellSize, cell.rot)
			if (cell.style.includes('line')) {
				stroke(cell.color)
				fill(cell.color2)
			} else {
				noStroke()
				fill(cell.color)
			}

			celldr[cell.style](this.cellSize, cell)

			pop()
		}
	}

	cellTransform(x, y, s, rot) {
		translate(x + s / 2, y + s / 2)
		rotate(rot)
		translate(-s / 2, -s / 2)
	}
}

let sketch

function setup() {
	createCanvas(windowWidth, windowHeight)
	sketch = new Sketch()
}

function draw() {
	clear()
	sketch.draw()
}

function drawColors() {
	var cols = colors

	cols.lights.forEach((color, i) => {
		var x = i * (width / cols.lights.length)
		fill(color)
		rect(x, 0, width / cols.lights.length, height / 9)
	})

	// cols.mids.forEach((color, i) => {
	//     let x = i * (width / cols.mids.length)
	//     fill(color)
	//     rect(x, height / 3, width / cols.mids.length, height / 3)
	// })

	cols.darks.forEach((color, i) => {
		var x = i * (width / cols.darks.length)
		fill(color)
		rect(x, (height / 9) * 8, width / cols.darks.length, height / 9)
	})
}

function mousePressed() {
	sketch.updateSizes()
	sketch.updateColors()
	sketch.updateCells()
}

